// radio_golden_2025_may_morning.js — Radiology 12 May Morning 2025 paper (148 source MCQs + 2 high-yield from MedGolden 19-23 at positions 141, 142 = 150 total)
// Schema: {q,o,a,e} with 5 options A-E and answer index 0-4
// Explanation: P1 mechanism + Take Notes discriminator chain (target ~50 words total)
if(!window.MM) window.MM={};
window.MM['radio_golden_2025_may_morning']=[
/*1*/ {"q":"In perforation of posterior wall of duodenum, which artery is involved?","o":["Gastroduodenal artery","Splenic artery","Gastroepiploic artery","Left gastric artery","Superior pancreaticoduodenal artery"],"a":0,"e":"Posterior duodenal ulcer perforation erodes the gastroduodenal artery lying behind D1, causing massive upper GI bleeding. Anterior perforation leads to free peritoneal spillage.<br><br>Take Notes: Splenic = posterior stomach | Left gastric = lesser curvature | Posterior duodenal wall = gastroduodenal artery."},
/*2*/ {"q":"Adductor longus nerve supply?","o":["Anterior part of obturator nerve","Posterior part of obturator nerve","Femoral nerve","Tibial nerve","Sciatic nerve"],"a":0,"e":"Adductor longus is supplied by the anterior division of obturator nerve (L2-L4); posterior division supplies adductor magnus (also tibial component). Femoral supplies pectineus partly.<br><br>Take Notes: Posterior obturator = adductor magnus | Tibial part = magnus hamstring | Adductor longus = anterior obturator division."},
/*3*/ {"q":"A young patient with blunt abdominal trauma, isolated liver injury on imaging, progressive drop in haemoglobin. Most appropriate initial management?","o":["Exploratory laparotomy","Blood transfusion and close monitoring","Angiographic embolization","Immediate damage control surgery","Observation without intervention"],"a":1,"e":"Hemodynamically stable patients with isolated liver injury are managed non-operatively with blood transfusion and serial monitoring; angiography reserved for ongoing bleeding. Exploration only if unstable.<br><br>Take Notes: Exploration = unstable patient | Angio embolization = persistent bleed | Stable liver injury = transfusion + monitoring."},
/*4*/ {"q":"Person with difficulty in swallowing, white growth inside oesophagus with pseudohyphae most likely cause:","o":["Candidiasis","Aspergillosis","Histoplasmosis","Mucor","Rhizopus"],"a":0,"e":"Candida albicans causes oesophageal candidiasis with white plaques and pseudohyphae on histology; common in immunocompromised (HIV, diabetes, steroids). Presents with dysphagia and odynophagia.<br><br>Take Notes: Aspergillus = septate, 45° branching | Mucor/Rhizopus = non-septate, 90° | Candida = pseudohyphae + white plaques."},
/*5*/ {"q":"During surgery for suspected appendicitis, the surgeon finds a 2cm mass at the base of appendix. What should be the next step in management?","o":["Appendectomy","Right hemicolectomy","Right extended hemicolectomy","Drain the collection","Take a biopsy and then close the abdomen"],"a":1,"e":"A 2cm mass at the appendiceal base raises suspicion for carcinoid or appendiceal tumour requiring oncological resection; right hemicolectomy is indicated for tumours >2 cm or involving caecal base.<br><br>Take Notes: <1 cm = appendectomy | >2 cm = right hemicolectomy | Appendiceal base mass 2cm = right hemicolectomy."},
/*6*/ {"q":"An epileptic lady who currently became pregnant on phenytoin is concerned about her medication. Which is correct?","o":["Add lithium","Switch phenytoin","Increase dose of phenytoin","Add valproic acid","Replace with barbiturates"],"a":1,"e":"Phenytoin is teratogenic (fetal hydantoin syndrome - cleft lip/palate, cardiac defects). In pregnancy, switch to safer alternatives like levetiracetam or lamotrigine for seizure control.<br><br>Take Notes: Valproate = worst teratogen (NTD) | Lithium = Ebstein anomaly | Pregnancy + epilepsy = switch phenytoin to safer drug."},
/*7*/ {"q":"Which of the following major vessels gives main contribution in anastomosis around hip joint?","o":["Internal iliac","Femoral","External iliac","Obturator","Pudendal"],"a":1,"e":"The cruciate and trochanteric anastomoses around the hip joint receive their major arterial contribution from the femoral artery via its lateral and medial circumflex femoral branches.<br><br>Take Notes: Obturator = posterior contribution | Internal iliac = via inferior gluteal | Hip joint anastomosis main supply = femoral artery."},
/*8*/ {"q":"A known smoker presents with abdominal pain, bloody vomit around 15 times. Most likely diagnosis:","o":["Peptic Ulcer Disease (PUD)","Gastric Carcinoma","Esophageal Carcinoma","Mallory-Weiss syndrome","Boerhaave syndrome"],"a":0,"e":"Peptic ulcer disease (especially gastric) commonly presents in smokers with epigastric pain and hematemesis; smoking impairs mucosal defence and slows ulcer healing. Most common cause of UGI bleed.<br><br>Take Notes: Mallory-Weiss = after retching | Boerhaave = transmural rupture | Smoker + abdominal pain + hematemesis = PUD."},
/*9*/ {"q":"In the aortic opening of the diaphragm, which structure will be compressed along with aorta?","o":["Azygos veins and both phrenic nerves","Thoracic duct and vagus nerve","Azygos vein and vagus nerve","Inferior vena cava","Thoracic duct and azygos vein"],"a":4,"e":"The aortic hiatus (T12) transmits aorta, thoracic duct, and azygos vein. The oesophageal hiatus (T10) transmits oesophagus with vagus nerves; IVC hiatus (T8) transmits IVC with right phrenic.<br><br>Take Notes: T8 caval = IVC + right phrenic | T10 = oesophagus + vagus | T12 aortic = aorta + thoracic duct + azygos."},
/*10*/ {"q":"After trauma on anatomical snuffbox, patient bleeds and pain due to which structure damaged?","o":["Lunate","Hamate","Scaphoid","Radius","Trapezium"],"a":2,"e":"The anatomical snuffbox floor is formed by the scaphoid bone; trauma here typically fractures the scaphoid (most commonly fractured carpal bone), with risk of avascular necrosis of proximal pole.<br><br>Take Notes: Lunate = perilunate dislocation | Hamate hook = handlebar | Snuffbox tenderness = scaphoid fracture."},
/*11*/ {"q":"A child presents with yellow discoloration of teeth. Which antibiotic was most likely taken by the mother during pregnancy?","o":["Amoxicillin","Ceftazidime","Ciprofloxacin","Co-Trimoxazole","Tetracycline"],"a":4,"e":"Tetracyclines chelate calcium in developing teeth and bones, causing permanent yellow-grey-brown discolouration of primary and permanent teeth; contraindicated in pregnancy and children <8 years.<br><br>Take Notes: Ciprofloxacin = cartilage damage | Co-trimoxazole = kernicterus near term | Tetracycline = yellow teeth + bone."},
/*12*/ {"q":"A 16-year-old patient presents with a 3-month history of neck swelling. On examination, there is a firm, non-tender mass in the left upper hypochondrium. Most likely diagnosis?","o":["Infectious mononucleosis","Hodgkin lymphoma","Acute lymphoblastic leukemia","Metastatic disease","Bacterial cervical lymphadenitis"],"a":1,"e":"Hodgkin lymphoma classically presents in young adults with painless, firm, rubbery cervical lymphadenopathy and possible hepatosplenomegaly (LUQ mass = spleen). Reed-Sternberg cells confirm diagnosis on biopsy.<br><br>Take Notes: Mono = tender, EBV+, atypical lymphocytes | ALL = pancytopenia + blasts | Young + painless nodes + splenomegaly = Hodgkin."},
/*13*/ {"q":"A baby after obstructed delivery presented with inability to abduct the arm and loss of flexion and loss of supination of arm at elbow joint due to damage to:","o":["Klumpke's paralysis","Erb's palsy","Radial nerve","Ulnar nerve","Median nerve"],"a":1,"e":"Erb's palsy: upper trunk (C5-C6) injury during obstructed delivery causes \"waiter's tip\" deformity — loss of shoulder abduction, elbow flexion, and forearm supination. Distal hand function intact.<br><br>Take Notes: Klumpke = lower trunk C8-T1, claw hand | Radial = wrist drop | Obstructed birth + waiter's tip = Erb's palsy."},
/*14*/ {"q":"A woman undergoes prolonged labor lasting 38 hours and delivers a baby vaginally. One hour after delivery, she suddenly develops dyspnea, cyanosis, hypotension, and rapidly progresses to shock and coma. Most likely diagnosis?","o":["Deep vein thrombosis (DVT)","Pulmonary embolism","Amniotic fluid embolism","Cervical tear with hemorrhagic shock","Cardiac tamponade"],"a":2,"e":"Amniotic fluid embolism: rare obstetric emergency with abrupt cardiopulmonary collapse, cyanosis, hypotension, and DIC after prolonged labour or precipitous delivery. High maternal mortality (>60%).<br><br>Take Notes: DVT = leg swelling | PE = pulmonary infarct picture | Sudden post-delivery collapse + DIC = amniotic fluid embolism."},
/*15*/ {"q":"Which of the following is a branch of the middle cerebral artery (MCA)?","o":["Anterior choroidal artery","Rolandic artery","Recurrent artery of Heubner","Callosomarginal artery","Posterior communicating artery"],"a":1,"e":"The Rolandic (central sulcus) artery is a cortical branch of the middle cerebral artery supplying the motor and sensory cortex around the central sulcus. Anterior choroidal is from ICA.<br><br>Take Notes: Heubner = ACA branch | Callosomarginal = ACA | Anterior choroidal = ICA | MCA branch = Rolandic artery."},
/*16*/ {"q":"Injury to the radial nerve at the wrist leads to:","o":["Wrist drop","Loss of sensation over dorsum of hand on lateral 2/3rd","Loss of sensation over medial 2½ fingers","Loss of arm sensation","Finger drop"],"a":1,"e":"Radial nerve at the wrist (after the superficial branch separates) gives only sensory innervation to dorsum of lateral hand; injury there causes sensory loss, not wrist drop (motor preserved).<br><br>Take Notes: Wrist drop = mid-humeral radial injury | Medial 2½ fingers = ulnar | Wrist-level radial = dorsum lateral 2/3 sensation."},
/*17*/ {"q":"Weakness of which of the following muscles is most likely to cause instability of the knee joint?","o":["Semimembranosus","Semitendinosus","Vastus lateralis","Vastus medialis","Rectus femoris"],"a":3,"e":"Vastus medialis (especially VMO) is crucial for patellar tracking and medial knee stability; its weakness causes patellofemoral instability and lateral patellar tracking, the commonest cause of knee instability.<br><br>Take Notes: Hamstrings = posterior stability | Rectus femoris = hip flexion + knee extension | Knee stability = vastus medialis (VMO)."},
/*18*/ {"q":"A patient after sciatic nerve injury having difficulty from sitting to standing position. What muscle is most likely injured?","o":["Gluteal muscles","Hamstring","Popliteus","Obturator internus","Iliopsoas"],"a":1,"e":"Sciatic nerve supplies hamstrings (semitendinosus, semimembranosus, long head of biceps femoris); their weakness impairs hip extension needed to rise from sitting and causes a steppage-type gait.<br><br>Take Notes: Gluteus maximus = inferior gluteal nerve | Popliteus = unlocks knee | Sciatic injury = hamstring weakness."},
/*19*/ {"q":"Patient had difficulty in standing and waddling gait. Nerve involves:","o":["Sciatic nerve","Femoral nerve","Obturator nerve","Superior gluteal nerve","Inferior gluteal nerve"],"a":3,"e":"Superior gluteal nerve injury weakens gluteus medius and minimus, causing Trendelenburg sign (pelvic drop on contralateral side) and a characteristic waddling/Trendelenburg gait when walking.<br><br>Take Notes: Inferior gluteal = gluteus maximus (rising) | Femoral = quads | Waddling gait = superior gluteal nerve."},
/*20*/ {"q":"Thoracodorsal artery arises from which part of brachial plexus?","o":["Lateral cord","Medial cord","Posterior cord","Axillary artery","Thoracoacromial artery"],"a":3,"e":"The thoracodorsal artery is a branch of the subscapular artery, which arises from the third part of the axillary artery; it supplies latissimus dorsi muscle (with thoracodorsal nerve).<br><br>Take Notes: Thoracodorsal nerve = posterior cord of plexus | Subscapular artery = axillary | Thoracodorsal artery = axillary artery."},
/*21*/ {"q":"A 44-year-old woman, gravida 3120 g (6 lb 14 oz), male infant. The pregnancy was uneventful except for decreased fetal movements compared to previous pregnancies. She declined amniocentesis. On examination, the antenatal period and dysmorphic facial features suggestive of Down syndrome. One hour after birth, develops bilious vomiting. Abdominal X-ray (KUB) reveals a characteristic \"double bubble\" sign. Most likely diagnosis?","o":["Hirschsprung disease","Duodenal atresia","Malrotation","Meconium ileus","Pyloric stenosis"],"a":1,"e":"Duodenal atresia is strongly associated with Down syndrome (30%); presents in first 24h with bilious vomiting and pathognomonic \"double bubble\" sign on X-ray (distended stomach and duodenum).<br><br>Take Notes: Hirschsprung = delayed meconium | Malrotation = bilious volvulus | Down + double bubble = duodenal atresia."},
/*22*/ {"q":"Shock in clinical terms refers to which of the following?","o":["Hypotension","Perfusion problem","Low oxygen saturation","Bradycardia","Fluid overload"],"a":1,"e":"Shock is defined as inadequate tissue perfusion leading to cellular hypoxia and organ dysfunction. Hypotension is common but not required — early shock can have normal BP.<br><br>Take Notes: Hypotension = late sign | Low O2 sat = hypoxemia | Shock = inadequate tissue perfusion."},
/*23*/ {"q":"Councilman bodies are found on investigation of a patient. What is the probable diagnosis?","o":["Apoptosis","Fat necrosis","Coagulative necrosis","Hepatitis","Yellow fever"],"a":4,"e":"Councilman bodies are apoptotic hepatocytes seen classically in yellow fever (also in viral hepatitis and toxic injury); they appear as eosinophilic, shrunken, round structures with pyknotic nuclei.<br><br>Take Notes: Apoptosis = general process | Hepatitis = also shows them | Pathognomonic association = yellow fever."},
/*24*/ {"q":"Pectoralis major flap will get blood supply from which of following?","o":["Intercostal arteries","Thoracoacromial","Lateral thoracic","Internal thoracic","Subscapular"],"a":1,"e":"The pectoralis major flap is based on the thoracoacromial artery (pectoral branch), which is the principal pedicle. The lateral thoracic provides only a minor contribution.<br><br>Take Notes: Lateral thoracic = serratus anterior | Internal thoracic = perforators | Pec major flap = thoracoacromial artery."},
/*25*/ {"q":"A patient during mastectomy. Which muscle located beneath the fascia is removed for movement to be affected?","o":["Abduction of the arm","External rotation of the shoulder joint","Flexion of the arm","Adduction of the arm","C (Pect major affected)"],"a":4,"e":"Mastectomy can involve removal of pectoralis major and/or minor fascia. Pectoralis major loss primarily affects arm adduction and medial rotation; pec major flap loss = adduction weakness.<br><br>Take Notes: Pec minor = scapular movement | Lat dorsi = adduction backup | Mastectomy + pec involvement = adduction lost."},
/*26*/ {"q":"Which of the following is the most common tumor at the cerebellopontine angle?","o":["Meningioma","Glioma","Ependymoma","Vestibular schwannoma","Medulloblastoma"],"a":3,"e":"Vestibular schwannoma (acoustic neuroma) is the most common cerebellopontine angle tumour (80-90%); arises from Schwann cells of vestibular nerve, presenting with hearing loss, tinnitus, vertigo.<br><br>Take Notes: Meningioma = 2nd most common CPA | Medulloblastoma = vermis | CPA tumour = vestibular schwannoma."},
/*27*/ {"q":"Which of the following lymphoid organs has a subcapsular region that receives afferent lymphatic vessels?","o":["Thymus","Lymph node","Spleen","Peyer's patch","Palatine tonsil"],"a":1,"e":"Lymph nodes have a distinct subcapsular sinus that receives afferent lymphatics; lymph percolates through cortex (B cells), paracortex (T cells), and medulla before efferent drainage at hilum.<br><br>Take Notes: Spleen = no afferent lymphatics | Thymus = no afferents | Subcapsular afferent lymph = lymph node."},
/*28*/ {"q":"All short muscles of hands supplied by:","o":["C7","T1","Ulnar nerve","Median nerve","C5-C6"],"a":1,"e":"Intrinsic hand muscles (lumbricals, interossei, thenar, hypothenar) are supplied by T1 spinal segment (via ulnar and median nerves). T1 controls all hand intrinsics.<br><br>Take Notes: Ulnar/median = peripheral nerves carrying T1 | C5-C6 = shoulder | All hand intrinsics root = T1."},
/*29*/ {"q":"Surgeon operated lady for enlarged thyroid, he ligated the superior and inferior pole as close to artery as possible. After 2 weeks she presented with hoarseness. Most likely cause could be injury to:","o":["Recurrent laryngeal nerve","Internal laryngeal nerve","External laryngeal nerve","Internal thoracic nerve","Vagus nerve"],"a":0,"e":"Recurrent laryngeal nerve runs in tracheo-oesophageal groove near inferior thyroid artery; its injury during thyroidectomy causes hoarseness due to ipsilateral vocal cord paralysis (in paramedian position).<br><br>Take Notes: External laryngeal = superior pole, voice pitch | Internal = sensory | Hoarseness post-thyroidectomy = recurrent laryngeal nerve."},
/*30*/ {"q":"A patient whose main trunk of radial nerve damage will present with:","o":["Finger drop","Ok sign","Loss of sensation over dorsum of hand on lateral 2/3","Loss of sensation over medial 2½ fingers","Loss of arm sensation"],"a":0,"e":"Main trunk radial nerve injury at axilla or upper humerus causes finger drop (loss of MCP extension) and wrist drop. Below extensor compartment innervation, motor signs predominate.<br><br>Take Notes: Ok sign loss = anterior interosseous (median) | Medial 2½ = ulnar | Radial trunk injury = finger drop."},
/*31*/ {"q":"A 60-year-old patient presents with rapidly progressive dementia, memory loss, and startle-induced myoclonus. His condition deteriorates rapidly and he dies within 6-12 months of symptom onset. Most likely diagnosis?","o":["Pick disease","Creutzfeldt-Jakob disease","Alcoholic Dementia","Kluver-Bucy syndrome","Alzheimer's disease"],"a":1,"e":"Creutzfeldt-Jakob disease (prion disease): rapidly progressive dementia with myoclonus, ataxia, and characteristic startle response. Death within 6-12 months. EEG shows periodic sharp wave complexes.<br><br>Take Notes: Alzheimer = slow over years | Pick = behavioural early | Rapid dementia + myoclonus = CJD."},
/*32*/ {"q":"A patient who recently underwent abdominal hysterectomy presents with severe postoperative pain not relieved by systemic analgesics. Most appropriate next step?","o":["Increase opioid infusion rate","Epidural Catheter","Transversus abdominis plane (TAP) block","Local anesthetic filtration at the site","Opioids alone"],"a":1,"e":"For severe post-hysterectomy pain unresponsive to systemic analgesics, epidural catheter analgesia provides excellent segmental pain relief, reduces opioid requirement, and improves recovery in major abdominal surgery.<br><br>Take Notes: TAP block = abdominal wall only | Increased opioids = side effects | Severe post-op + failed analgesics = epidural catheter."},
/*33*/ {"q":"A 10-week pregnant woman presents with persistent nausea, vomiting and noticeable weight loss. Most likely diagnosis?","o":["Gout","Hyperemesis gravidarum","Gastroenteritis","Molar pregnancy","Urinary tract infection"],"a":1,"e":"Hyperemesis gravidarum: severe persistent vomiting in early pregnancy (<16 weeks) with >5% weight loss, dehydration, ketonuria, and electrolyte disturbances. Linked to elevated hCG levels.<br><br>Take Notes: Molar pregnancy = snowstorm USG, very high hCG | Gastroenteritis = diarrhoea | 10w pregnant + severe vomiting = hyperemesis gravidarum."},
/*34*/ {"q":"Corpus luteum secretes mainly to maintain pregnancy:","o":["Progesterone","Inhibin","BHCG","Estrogen","FSH"],"a":0,"e":"Corpus luteum secretes progesterone (with some estrogen and inhibin) to maintain endometrium and pregnancy until placenta takes over at week 8-10. Progesterone is its primary secretory product.<br><br>Take Notes: BHCG = placenta, not corpus luteum | Estrogen = secondary | Corpus luteum = progesterone (primary)."},
/*35*/ {"q":"Overlapping of L5 vertebra on sacrum is called:","o":["Spondylosis","Spondiectisis","Spondylolisthesis","Retrodicitesis","Spondylolysis"],"a":2,"e":"Spondylolisthesis is anterior displacement (slippage) of a vertebra over the one below; most commonly L5-S1. Causes back pain, neurogenic claudication, and possible nerve root compression.<br><br>Take Notes: Spondylolysis = pars defect (no slip) | Spondylosis = degenerative disc | L5 over S1 slip = spondylolisthesis."},
/*36*/ {"q":"A 35-year-old woman with heavy menstrual bleeding and dysmenorrhea now presents with worsening menstrual pain for 2 months. Bimanual pelvic examination: ovaries normal, uterus uniformly enlarged and tender. Most likely diagnosis:","o":["Uterine fibroids (leiomyoma)","Adenomyosis","Endometriosis","Endometritis","Chronic pelvic inflammatory disease"],"a":1,"e":"Adenomyosis: ectopic endometrial tissue within myometrium causing diffusely enlarged, tender, boggy uterus with heavy painful menses. Affects parous women in 30s-40s; MRI confirms diagnosis.<br><br>Take Notes: Fibroids = lumpy, asymmetric | Endometriosis = nodules, fixed pelvis | Tender, diffusely enlarged uterus = adenomyosis."},
/*37*/ {"q":"Baby with some red structure coming out above symphysis pubis, frequently getting wet, on examination epispadia and incomplete closure of pubic symphysis:","o":["Bladder exstrophy","Incomplete cephalocaudal folding","Incomplete lateral folding","Failed reinforcement of the cloacal membrane by underlying mesenchyme","Urachal anomaly"],"a":0,"e":"Bladder exstrophy results from failed reinforcement of the cloacal membrane by underlying mesenchyme during embryonic development; exposed bladder mucosa, epispadias, and pubic diastasis classically present.<br><br>Take Notes: Cephalocaudal folding = stomodeum/proctodeum | Lateral folding = gastroschisis | Bladder exstrophy = failed cloacal membrane reinforcement."},
/*38*/ {"q":"Structure damage in fracture of sacrum and ischial spine:","o":["Coccyx","Anus","Rectum","Ilium","Uterus"],"a":2,"e":"The rectum lies in close anatomical relation to the sacrum and ischial spine; pelvic fractures involving these structures can lacerate the rectum, causing perirectal hemorrhage and infection.<br><br>Take Notes: Coccyx = separate fracture | Anus = perineal injury | Sacrum/ischial spine fracture = rectum injury."},
/*39*/ {"q":"What is the most common cause of spontaneous subarachnoid hemorrhage (SAH)?","o":["Head trauma","Hypertension","Ruptured berry aneurysm","Arteriovenous malformation (AVM)","Cerebral amyloid angiopathy"],"a":2,"e":"Ruptured saccular (berry) aneurysm causes 80% of spontaneous SAH; commonly at anterior communicating artery in the Circle of Willis. Presents with thunderclap headache and meningism.<br><br>Take Notes: Head trauma = traumatic SAH (not spontaneous) | AVM = 10% | Spontaneous SAH = ruptured berry aneurysm."},
/*40*/ {"q":"Which vitamin is most commonly associated with anti-aging properties due to its antioxidant effect?","o":["Vitamin C","Vitamin K","Vitamin B complex","Vitamin E","Vitamin D"],"a":3,"e":"Vitamin E (alpha-tocopherol) is the principal lipid-soluble antioxidant, protecting cell membranes from lipid peroxidation by free radicals; widely marketed for anti-aging skin care.<br><br>Take Notes: Vitamin C = water-soluble antioxidant | Vitamin K = clotting | Anti-aging antioxidant = vitamin E."},
/*41*/ {"q":"Edema in kidney related disease in patient is due to:","o":["Salt and water retention","Hypoalbuminemia","Increase hydrostatic pressure","Increase oncotic pressure","Portal HTN"],"a":1,"e":"Nephrotic syndrome causes massive proteinuria (>3.5 g/day) with hypoalbuminemia; reduced plasma oncotic pressure drives fluid into the interstitium, producing characteristic periorbital and dependent edema.<br><br>Take Notes: Salt retention = CHF | Hydrostatic = venous | Renal edema (nephrotic) = hypoalbuminemia."},
/*42*/ {"q":"A patient presented with pain and absolute constipation. O/E abdominal distension and an incisional scar seen. On the right side of the scar there is swelling that is bulging outwards and tender. X-ray reveals dilated small bowel loops and multiple air fluid levels. Most probable diagnosis?","o":["Acute Intestinal obstruction","Chronic Intestinal obstruction","Volvulus","Strangulated Incisional hernia","Obstructed Hernia"],"a":3,"e":"Strangulated incisional hernia: incarcerated hernia with vascular compromise — tender, irreducible swelling at incision site with bowel obstruction features. Requires emergency surgery to prevent bowel necrosis.<br><br>Take Notes: Simple incisional = reducible, painless | Obstructed = not tender | Tender bulge + obstruction = strangulated incisional hernia."},
/*43*/ {"q":"A 35-year-old woman presents with sudden-onset dyspnea and mild pleuritic chest pain. She has no history of lung disease. Her vital signs are stable, oxygen saturation 95% on room air. You suspect pulmonary embolism (PE). Most appropriate initial investigation to help rule out PE in this stable patient?","o":["Arterial blood gases (ABG)","Chest X-ray","D-dimer test","CT pulmonary angiography (CTPA)","ECG"],"a":2,"e":"In hemodynamically stable patients with low/intermediate clinical probability of PE, D-dimer test is the appropriate initial screen; a negative D-dimer effectively rules out PE (high sensitivity).<br><br>Take Notes: CTPA = confirmatory after positive D-dimer | ABG = non-specific | Stable patient + PE suspicion = D-dimer first."},
/*44*/ {"q":"A 45-year-old man with a long history of alcoholism presents with severe epigastric pain, nausea, vomiting, fever, and increase in serum amylase. Diagnosis of acute pancreatitis superimposed on chronic pancreatitis was made. Which type of necrosis is most characteristic?","o":["Coagulative necrosis","Fat necrosis","Fibrinoid","Caseous","Liquefactive necrosis"],"a":1,"e":"Acute pancreatitis releases lipase that hydrolyses adipose tissue triglycerides, causing fat necrosis. Free fatty acids precipitate with calcium forming chalky white \"soap saponification\" - pathognomonic finding.<br><br>Take Notes: Coagulative = MI, kidney | Caseous = TB | Pancreatitis = fat necrosis (saponification)."},
/*45*/ {"q":"A 25-year-old man is evaluated for infertility. Physical examination is unremarkable. Testicular biopsy reveals isolated atrophy of the seminiferous tubules, while Leydig cells appear preserved. Most likely diagnosis?","o":["Klinefelter syndrome","Hydrocele","Mumps orchitis","Cryptorchidism","Prior Chemotherapy"],"a":3,"e":"Cryptorchidism (undescended testis) causes germ cell loss with seminiferous tubule atrophy due to higher abdominal temperature; Leydig cells (testosterone-producing) are relatively preserved. Increases testicular cancer risk.<br><br>Take Notes: Klinefelter = hyalinised tubules + small testes + 47,XXY | Mumps = post-pubertal orchitis | Tubule atrophy + Leydig preserved = cryptorchidism."},
/*46*/ {"q":"A middle aged woman presents with a midline epigastric mass noticed after recent abdominal surgery. The mass becomes prominent on coughing or straining. On examination, there is no palpable fascial defect and no signs of incarceration or tenderness. What is the most likely diagnosis?","o":["Divarication of recti","Incisional hernia","Epigastric hernia","Ventral hernia","Spigelian hernia"],"a":0,"e":"Divarication of recti: separation of rectus abdominis muscles without fascial defect; midline epigastric bulge on straining, no palpable defect, no incarceration risk. Common after pregnancy or surgery.<br><br>Take Notes: Incisional hernia = palpable defect | Epigastric = small fascial defect | No defect + midline bulge = divarication of recti."},
/*47*/ {"q":"A patient presents with Head of fibula fracture leading to loss of dorsiflexion and lateral rotation along with loss of sensation over the lateral aspect of the leg and the dorsum of the foot. Which nerve is most likely injured?","o":["Superficial peroneal nerve","Deep peroneal nerve","Common peroneal nerve","Tibial nerve","Sural nerve"],"a":2,"e":"Common peroneal nerve winds around fibular neck — vulnerable to fracture; injury causes foot drop (loss of dorsiflexion and eversion) and sensory loss over lateral leg and dorsum of foot.<br><br>Take Notes: Deep peroneal = dorsiflexion + web space sensation | Superficial = eversion + dorsum | Fibular neck = common peroneal nerve."},
/*48*/ {"q":"A couple presents with infertility for 1 year. The female partner reports irregular menstrual cycles and galactorrhea. Investigations show elevated serum prolactin, slightly raised TSH, and normal pelvic ultrasound. The male partner's semen analysis is normal. What is the most likely cause of the infertility?","o":["Prolactinoma","Polycystic ovarian syndrome (PCOS)","Hypothyroidism","Functional hypothalamic amenorrhea","Premature ovarian insufficiency"],"a":0,"e":"Prolactinoma (pituitary adenoma secreting prolactin) causes hyperprolactinemia, galactorrhea, amenorrhea, and infertility. Elevated TSH may co-exist due to TRH stimulating prolactin in primary hypothyroidism.<br><br>Take Notes: PCOS = high LH/FSH ratio, hirsutism | Hypothyroidism = secondary cause | Galactorrhea + amenorrhea + infertility = prolactinoma."},
/*49*/ {"q":"A 45-year-old female presents with bone pain and paresthesia in the lower limbs. Her laboratory investigations were done and showed Serum Calcium 2.60 mmol/L (2.10-2.65 mmol/L Normal), inorganic 0.9 mmol/L (0.8-1.9 mmol/L Normal), ALP 385 IU/L (Normal 120-365 IU/L), serum PTH levels were borderline raised; 6.1 mmol/L (Normal 1.5-6.0). What is the most likely diagnosis?","o":["Primary hyperparathyroidism","Pseudohyperparathyroidism","Secondary hyperparathyroidism","Tertiary hyperparathyroidism","Ectopic Malignancy"],"a":0,"e":"Mild hypercalcemia with raised PTH and ALP indicates primary hyperparathyroidism (most likely parathyroid adenoma). Bone pain and paresthesia reflect hypercalcemic effects on nerves and bone remodelling.<br><br>Take Notes: Secondary = low calcium + high PTH | Tertiary = high Ca + very high PTH (CKD) | Normal-high Ca + raised PTH = primary hyperparathyroidism."},
/*50*/ {"q":"A patient with anemia receives treatment. To determine whether the patient is producing blood cells versus losing them, transfusion counts due to bleeding, the following test is most helpful:","o":["Hemoglobin electrophoresis","Reticulocyte count","MCH","Serum ferritin","Mean corpuscular volume (MCV)"],"a":1,"e":"Reticulocyte count measures young RBCs released from bone marrow; elevated reticulocytes indicate active erythropoiesis (response to blood loss/hemolysis), while low count indicates production failure (aplastic, deficiency anemias).<br><br>Take Notes: Hb electrophoresis = hemoglobinopathy diagnosis | Ferritin = iron stores | Production vs loss = reticulocyte count."},
/*51*/ {"q":"A patient with beta-thalassemia major is on regular blood transfusions. He presents with hepatosplenomegaly, and lab tests show elevated serum ferritin. What is the most likely cause?","o":["Hemochromatosis","Viral hepatitis","Autoimmune hepatitis","Wilson's disease","Acute liver failure"],"a":0,"e":"Repeated blood transfusions in beta-thalassemia cause secondary iron overload (transfusional hemochromatosis); iron deposits in liver, heart, pancreas causing hepatosplenomegaly and raised ferritin. Treated with chelation.<br><br>Take Notes: Viral hepatitis = transaminitis | Wilson = low ceruloplasmin | Multiple transfusions + ferritin↑ = hemochromatosis."},
/*52*/ {"q":"A young woman presents with painful genital ulcers extending from the cervix to the introitus. There is associated dysuria and tender inguinal lymphadenopathy. Most likely diagnosis:","o":["Syphilis","Behcet's disease","Genital herpes","Chancroid","Lichen planus"],"a":2,"e":"Genital herpes (HSV-2): painful, multiple, vesicular ulcers with tender inguinal lymphadenopathy and dysuria. Primary outbreak is more severe with systemic symptoms; recurrent episodes are milder.<br><br>Take Notes: Syphilis chancre = painless | Chancroid = painful (Haemophilus ducreyi) | Painful vesicular ulcers + tender nodes = HSV."},
/*53*/ {"q":"In which of the following areas the vomiting center is located:","o":["Thalamus","Hypothalamus","Medulla oblongata","Pons","Cortex"],"a":2,"e":"The vomiting (emetic) center is located in the medulla oblongata, near the nucleus tractus solitarius; it receives inputs from chemoreceptor trigger zone (area postrema), GI tract, and vestibular system.<br><br>Take Notes: CTZ = area postrema (outside BBB) | Thalamus = relay | Vomiting center = medulla oblongata."},
/*54*/ {"q":"Corpus luteum secretes mainly to maintain pregnancy:","o":["Progesterone","Inhibin","BHCG","Estrogen","FSH"],"a":0,"e":"Corpus luteum is the primary source of progesterone in early pregnancy (until 8-10 weeks); progesterone maintains decidualisation and prevents myometrial contractions. Inhibin and estrogen are secondary products.<br><br>Take Notes: BHCG = placental, maintains corpus luteum | Estrogen = secondary | Corpus luteum main = progesterone."},
/*55*/ {"q":"Which one is autosomal dominant disorder?","o":["Thalassemia","Sickle cell anemia","Familial adenomatous polyposis (FAP)","Hemophilia","Cystic fibrosis"],"a":2,"e":"FAP is autosomal dominant; APC tumor suppressor mutation causes >100 colon polyps in adolescence with nearly 100% malignant transformation by age 40 if untreated by prophylactic colectomy.<br><br>Take Notes: Sickle/thalassemia/CF = autosomal recessive | Hemophilia = X-linked | FAP = autosomal dominant (APC)."},
/*56*/ {"q":"Rate of sickling influenced by:","o":["Hb S concentration","Hypoxia","Acidosis","Dehydration","Infection"],"a":0,"e":"The rate and extent of HbS polymerisation (sickling) primarily depends on HbS concentration in the RBC; higher HbS% (homozygous SS) causes faster sickling than heterozygous (sickle trait, AS).<br><br>Take Notes: Hypoxia/acidosis/dehydration = triggers but secondary | HbS concentration = primary determinant."},
/*57*/ {"q":"Most prone to ischemic:","o":["Kidney","Skeletal muscle","Neuron","Heart","Skin"],"a":2,"e":"Neurons are most susceptible to ischemic injury; irreversible neuronal damage occurs after 3-5 minutes of complete cerebral ischemia. Heart muscle tolerates 20-40 minutes; skeletal muscle 4-6 hours.<br><br>Take Notes: Heart = 20-40 min tolerance | Kidney = 20 min | Most ischemia-sensitive = neuron."},
/*58*/ {"q":"Which of the following amino acid substitution is responsible for sickle cell anemia?","o":["Valine for Glutamic acid","Lysine for Glutamic acid","Glutamic acid for valine","Glutamic acid for Lysine","Leucine for Lysine"],"a":0,"e":"Sickle cell anemia: GAG→GTG point mutation in β-globin codon 6 substitutes valine (hydrophobic) for glutamic acid (hydrophilic); this enables HbS polymerisation under deoxygenated conditions causing sickling.<br><br>Take Notes: HbS = β6 Glu→Val | HbC = β6 Glu→Lys | Sickle = Valine replaces glutamic acid."},
/*59*/ {"q":"Prenatal screening of open neural tube defects:","o":["CVS","Amniocentesis","USG","NIPT","Maternal serum AFP"],"a":1,"e":"Amniocentesis (typically 15-20 weeks) measures amniotic fluid AFP and acetylcholinesterase, both elevated in open NTDs (anencephaly, spina bifida). USG also screens but amniocentesis confirms.<br><br>Take Notes: Maternal serum AFP = screening | USG = detection | CVS = chromosomal not NTD | Open NTD definitive = amniocentesis."},
/*60*/ {"q":"Which vein moves perpendicular and over Sternocleidomastoid, pierces fascia in neck:","o":["IJV","EJV","Retromandibular vein","Intercostal vein","Thoracic vein"],"a":1,"e":"External jugular vein (EJV) runs perpendicular over sternocleidomastoid muscle from angle of mandible to mid-clavicle, then pierces investing layer of cervical fascia to drain into subclavian vein.<br><br>Take Notes: IJV = deep, within carotid sheath | Retromandibular = parotid | Over SCM + pierces fascia = EJV."},
/*61*/ {"q":"How much cm of small intestine is involved in absorption of nutrients?","o":["100 cm","20 cm","50 cm","120 cm","200 cm"],"a":0,"e":"Most nutrient absorption occurs in the first 100-200 cm of small intestine (jejunum + proximal ileum); short bowel syndrome develops when residual small bowel <100 cm post-resection.<br><br>Take Notes: Duodenum = iron, calcium | Distal ileum = B12, bile salts | Main absorption length = ~100 cm."},
/*62*/ {"q":"1st cervical nerve supply:","o":["Omohyoid","Geniohyoid","Platysma","Serratus anterior","Sternohyoid"],"a":1,"e":"The first cervical (C1) nerve travels along the hypoglossal nerve and supplies geniohyoid and thyrohyoid muscles. It does not have a typical cutaneous branch; mainly motor via C1 fibers.<br><br>Take Notes: Omohyoid/sternohyoid = ansa cervicalis C1-C3 | Platysma = facial nerve | Pure C1 = geniohyoid (via XII)."},
/*63*/ {"q":"Skeleton is dug out of grave. How to know if it is female pelvis?","o":["Everted Iliac Ala","Heart Shaped Pelvis","Inverted Ischial spines at the Mid","Fused Ischial spines at the Mid","Subpubic angle <90°"],"a":0,"e":"Female pelvis (gynaecoid): wider, shallower, with everted iliac alae, oval inlet, wider subpubic angle (>90°), shorter sacrum, and everted ischial tuberosities — adaptations for childbirth.<br><br>Take Notes: Heart-shaped pelvis = android (male) | Subpubic angle <90° = male | Female pelvis = everted iliac ala."},
/*64*/ {"q":"Diabetes patient started on Garlgine (glargine) insulin. True about it:","o":["No peak","Affect on post prandial hyperglycemia","Long acting because act on protein binding","Should not be given with other insulin types","Causes weight gain"],"a":0,"e":"Insulin glargine is a long-acting basal insulin with no pronounced peak (peakless); duration ~24 hours providing constant basal coverage. Cannot be mixed with other insulins in same syringe.<br><br>Take Notes: Postprandial control = rapid-acting (lispro, aspart) | Insulin glargine = long-acting, no peak."},
/*65*/ {"q":"A diabetic patient started on a new medication presents with burning micturition. Which drug is most likely responsible?","o":["Metformin","Canagliflozin","Glimepiride","Pioglitazone","Sitagliptin"],"a":1,"e":"SGLT2 inhibitors (canagliflozin, empagliflozin) cause glucosuria, predisposing to urogenital infections including UTI and genital candidiasis (burning micturition). Glycosuria provides substrate for organisms.<br><br>Take Notes: Metformin = GI side effects | Pioglitazone = weight gain | New diabetes drug + UTI = SGLT2 inhibitor (canagliflozin)."},
/*66*/ {"q":"A female patient consuming licorice experiences effects due to inhibition of which enzyme involved in cortisol metabolism?","o":["11β-Hydroxylase","17α-Hydroxylase","11β-Hydroxysteroid dehydrogenase type 2","21-Hydroxylase","Aldosterone synthase"],"a":2,"e":"Licorice (glycyrrhetinic acid) inhibits 11β-HSD2 in kidney, preventing cortisol→cortisone conversion. Excess cortisol activates mineralocorticoid receptors, causing apparent mineralocorticoid excess (hypertension, hypokalemia, alkalosis).<br><br>Take Notes: 21-hydroxylase deficiency = CAH | Aldosterone synthase = Conn | Licorice = 11β-HSD2 inhibition."},
/*67*/ {"q":"Oral glucose has better metabolism than IV glucose because of:","o":["VIP induced GLIP","CCK induced Insulin","GLP induced GIP","CCK induced VIP","GLP-1 induced insulin"],"a":4,"e":"Oral glucose triggers GLP-1 release from intestinal L-cells, which stimulates pancreatic insulin secretion (incretin effect). This is why oral glucose causes greater insulin response than equivalent IV glucose.<br><br>Take Notes: GIP = also incretin (from K-cells) | CCK = gallbladder, pancreas | Oral > IV glucose = incretin effect (GLP-1)."},
/*68*/ {"q":"Two solutions A with 1 mole of glucose and B with 1 mole of NaCl. What would be the osmotic pressure?","o":["Initiating movement of solute from A to B","Initiating movement of solvent from B to A","Stopping movement of solute from B to B","Stopping movement of solvent from B to A","Equal pressure"],"a":1,"e":"NaCl dissociates into Na+ and Cl- (2 osmoles) while glucose is 1 osmole; solution B has higher osmotic pressure. Water (solvent) moves from B to A reversed — actually toward B.<br><br>Take Notes: Osmosis = solvent movement | Higher osmolarity = pulls water | NaCl > glucose osmotically."},
/*69*/ {"q":"Tissue damage from ionising radiation depends on:","o":["Type of tissue","Duration of exposure","Type of radiation","Patient's age","All of these"],"a":1,"e":"Radiation tissue damage depends on cumulative dose, which is product of dose rate and duration of exposure. Tissue radiosensitivity, type of radiation, and individual factors also contribute.<br><br>Take Notes: Multiple factors apply | Cumulative dose = key principle | Duration of exposure = major determinant."},
/*70*/ {"q":"A patient with a skull fracture after a road traffic accident (RTA) is scheduled for surgery. Extra caution during surgery should be taken to prevent:","o":["Fat embolism","Pulmonary embolism (PE)","Thrombus formation","Air embolism","Subdural hematoma extension"],"a":3,"e":"In skull surgery, especially sitting position or with dural sinus injury, air can enter venous sinuses causing venous air embolism — potentially fatal. Precautions include head-down positioning and careful technique.<br><br>Take Notes: Fat embolism = long bone fracture | PE = leg DVT | Skull/sinus surgery = air embolism."},
/*71*/ {"q":"Lymphoma patient on ABVD therapy. Lung complications due to:","o":["Bleomycin","Vinblastine","Vincristine","Doxorubicin","Dacarbazine"],"a":0,"e":"ABVD regimen for Hodgkin lymphoma: Bleomycin causes pulmonary fibrosis (dose-related, can be fatal); requires PFT monitoring during treatment. Other components have different toxicities.<br><br>Take Notes: Doxorubicin = cardiotoxicity | Vincristine = neuropathy | ABVD lung toxicity = bleomycin."},
/*72*/ {"q":"For caudal block, the base of equilateral triangle formed by sacral hiatus:","o":["At greater trochanteric lines","Joining post sup iliac spines","Joining ant sup iliac spines","Trochanteric line","Joining ischial tuberosities"],"a":2,"e":"For caudal epidural block, sacral hiatus and the two posterior superior iliac spines (PSIS) form an equilateral triangle; PSIS line is the base, sacral hiatus is the apex. Landmark for needle insertion.<br><br>Take Notes: Sacral hiatus = apex | PSIS = base of triangle | Caudal block triangle = PSIS line as base."},
/*73*/ {"q":"A patient presents with small (<1 cm) lung nodules on imaging. Histopathology shows granulomas without necrosis. Most likely diagnosis?","o":["Tuberculosis","Sarcoidosis","Pneumocystis jirovecii infection","Leprosy","Histoplasmosis"],"a":1,"e":"Non-caseating granulomas in lung are characteristic of sarcoidosis: multisystem disease with bilateral hilar lymphadenopathy, non-caseating granulomas, elevated ACE. Affects young adults.<br><br>Take Notes: TB = caseous necrosis | Pneumocystis = no granulomas | Non-caseating granulomas = sarcoidosis."},
/*74*/ {"q":"A patient presents with confusion, dizziness, bradycardia (HR 55 bpm), hypotension, and signs of increased intracranial pressure (ICP). Which of the following reflexes is most likely activated?","o":["Bainbridge reflex","CNS ischemic response","Baroreceptor reflex","Chemoreceptor reflex","Vagal reflex"],"a":1,"e":"CNS ischemic response (Cushing reflex): raised ICP causes brainstem ischemia, triggering sympathetic surge with hypertension (compensatory) and reflex bradycardia. Classic Cushing triad: hypertension, bradycardia, irregular respiration.<br><br>Take Notes: Bainbridge = tachycardia from atrial stretch | Baroreceptor = BP feedback | Raised ICP = CNS ischemic response."},
/*75*/ {"q":"Regarding preferential thorough fare channel, correct statement is:","o":["Small caliber","Having smooth muscles","Open on demand","Present at origin of precapillary sphincter","Venous vessel"],"a":3,"e":"Preferential (thoroughfare) channels are direct connections from arterioles to venules bypassing the capillary bed; they originate at the precapillary sphincter level and remain open even when sphincters are closed.<br><br>Take Notes: Capillaries = open on demand (via sphincters) | Smooth muscles = arteriole | Thoroughfare channel = origin at precapillary sphincter."},
/*76*/ {"q":"One month after a cerebral infarction (stroke), which of the following cell types predominantly contributes to the repair and scarring process in the affected brain tissue?","o":["Astrocytes","Microglia","Oligodendrocytes","Neurons","Schwann cells"],"a":0,"e":"After cerebral infarction, astrocytes proliferate at the lesion edges to form glial scar (gliosis); this is the CNS equivalent of fibrous scarring. Microglia clear debris early, then astrogliosis dominates.<br><br>Take Notes: Microglia = early macrophage role | Oligodendrocytes = myelinate | CNS scar = astrocytes (gliosis)."},
/*77*/ {"q":"Macrophages are derived from:","o":["B cells","Dendrites","Monocytes","Plasma cells","Eosinophils"],"a":2,"e":"Tissue macrophages develop from circulating blood monocytes (originating in bone marrow). On entering tissues, monocytes differentiate into macrophages with various specialised functions (Kupffer, alveolar, microglia).<br><br>Take Notes: B cells = antibodies | Plasma cells = matured B cells | Macrophages = from monocytes."},
/*78*/ {"q":"Most important reflex for defecation:","o":["Rectoanal","Mass movement","Parasympathetic","Sympathetic","Internal anal sphincter"],"a":0,"e":"The rectoanal inhibitory reflex (RAIR): rectal distension causes reflex relaxation of internal anal sphincter, signalling readiness for defecation. Loss of this reflex = Hirschsprung disease.<br><br>Take Notes: Mass movements = colon transport | Parasympathetic = facilitates | Defecation reflex = rectoanal (RAIR)."},
/*79*/ {"q":"Correct sequence of events for neutrophil migration toward the site of acute inflammation is:","o":["Margination, adhesion, rolling, transmigration","Margination, rolling, adhesion, transmigration","Rolling, adhesion, margination, transmigration","Transmigration, rolling, adhesion, margination","Adhesion, margination, rolling, transmigration"],"a":1,"e":"Neutrophil extravasation sequence: (1) Margination — neutrophils move to vessel periphery; (2) Rolling — selectin-mediated; (3) Adhesion — firm attachment via integrins; (4) Transmigration — through endothelium.<br><br>Take Notes: Selectins = rolling | Integrins = firm adhesion | Order = margination → rolling → adhesion → transmigration."},
/*80*/ {"q":"Maximum number of beta cells in islets of Langerhans are present in:","o":["Neck of pancreas","Tail of pancreas","Body of pancreas","Head of pancreas","Ampulla of Vater"],"a":1,"e":"The tail of pancreas contains the highest density of islets of Langerhans (beta cells producing insulin). Distal pancreatectomy can lead to diabetes due to loss of beta cell mass.<br><br>Take Notes: Head = exocrine predominant | Body/neck = intermediate | Maximum beta cells = tail of pancreas."},
/*81*/ {"q":"Which of the following tumor marker is positive in ovarian carcinoma?","o":["CA 123","CA 125","AFP","LDH","CEA"],"a":1,"e":"CA 125 is the principal tumor marker for epithelial ovarian carcinoma (raised in >80% serous type); used for diagnosis, monitoring response, and detecting recurrence. Also elevated in endometriosis.<br><br>Take Notes: AFP = yolk sac, HCC | LDH = dysgerminoma | CEA = colon | Ovarian CA = CA 125."},
/*82*/ {"q":"Cephalosporin mechanism of action:","o":["Inhibit protein","Inhibits transpeptidase","Inhibit lipid","Inhibit mycolic acid","Inhibits ribosomes"],"a":1,"e":"Cephalosporins (like all β-lactams) inhibit bacterial cell wall transpeptidase enzymes (penicillin-binding proteins), preventing peptidoglycan cross-linking. Result is bacterial lysis from osmotic instability.<br><br>Take Notes: Aminoglycosides = 30S ribosome | Macrolides = 50S | Mycolic acid = INH (TB) | Cephalosporins = transpeptidase."},
/*83*/ {"q":"A peritoneal mass is compressing the abdominal aorta, reducing its diameter by 50%. According to Poiseuille's law, by approximately how much does the vascular resistance increase?","o":["2-fold","4-fold","8-fold","12-fold","16-fold"],"a":4,"e":"Poiseuille's law: resistance ∝ 1/r⁴. Halving radius increases resistance by 2⁴ = 16-fold. Small vessel changes have dramatic effects on resistance and flow.<br><br>Take Notes: Halved radius = 16-fold resistance | Doubled radius = 1/16 resistance | r⁴ relationship governs vascular resistance."},
/*84*/ {"q":"An infant passes stools shortly after every feeding. A biopsy of the intestinal mucosa shows loss of microvilli (brush border damage). Which of the following enzyme deficiencies is most likely responsible for the symptoms?","o":["Lactase","Sucrase","Maltase","Isomaltase","Enterokinase"],"a":0,"e":"Lactase is the most apical brush-border enzyme; even mild villous damage causes secondary lactase deficiency. Undigested lactose causes osmotic diarrhoea with stools after feeds (lactose in formula/milk).<br><br>Take Notes: Sucrase/maltase = deeper enzymes | Enterokinase = trypsin activator | Brush border + feeding diarrhoea = lactase deficiency."},
/*85*/ {"q":"Moderate diarrhea will lead to which of the following fluid changes?","o":["Decreased intracellular fluid (ICF) only","Decreased extracellular fluid (ECF) only","Decreased both intracellular and extracellular fluid","Increased extracellular fluid (ECF)","No significant fluid loss"],"a":2,"e":"Moderate diarrhoea causes isotonic fluid loss from the gut; this initially depletes ECF, then water redistributes from ICF to ECF, ultimately depleting both compartments. Resulting in dehydration.<br><br>Take Notes: Severe diarrhoea = hyponatremic, water shifts | Pure water loss = ICF | Moderate diarrhoea = both ICF + ECF decrease."},
/*86*/ {"q":"Anterior tongue numbness after submandibular gland surgery indicates injury to:","o":["Glossopharyngeal nerve","Hypoglossal nerve","Lingual nerve","Facial nerve","Vagus nerve"],"a":2,"e":"Lingual nerve (branch of mandibular V3) provides general sensation to anterior 2/3 of tongue and runs close to submandibular gland; vulnerable during submandibular surgery. Damage causes anterior tongue numbness.<br><br>Take Notes: Hypoglossal = motor to tongue | Glossopharyngeal = posterior 1/3 sensation | Anterior tongue numbness = lingual nerve."},
/*87*/ {"q":"A patient with bacterial meningitis. What is the most appropriate initial drug regimen?","o":["Ceftriaxone plus Azithromycin","Ceftriaxone plus Vancomycin","Ceftriaxone plus dexamethasone","Ceftriaxone plus azithromycin","Ceftriaxone plus ampicillin"],"a":2,"e":"Empirical bacterial meningitis: third-generation cephalosporin (ceftriaxone) covers pneumococcus and meningococcus; dexamethasone reduces inflammatory complications and improves outcomes (especially pneumococcal). Vancomycin added if resistant pneumococcus suspected.<br><br>Take Notes: Vancomycin = MRSA coverage | Ampicillin = listeria (extremes of age) | Standard adult meningitis = ceftriaxone + dexamethasone."},
/*88*/ {"q":"Poiseuille's law: by approximately how much does the vascular resistance increase if radius is halved?","o":["2-fold","4-fold","8-fold","12-fold","16-fold"],"a":4,"e":"Poiseuille's equation: resistance is inversely proportional to fourth power of radius (r⁴). Halving radius = (1/2)⁻⁴ = 16-fold increase in resistance. Small radius changes dramatically affect blood flow.<br><br>Take Notes: Flow ∝ r⁴ | Resistance ∝ 1/r⁴ | Halved radius = 16x resistance increase."},
/*89*/ {"q":"A patient undergoes imaging after dye injection. The dye is completely cleared from the left kidney, but not from the right side. Additionally, some dye is detected above the bladder. Which of the following is most likely diagnosis?","o":["Horseshoe kidney","Renal agenesis on one side","Pelvic kidney","Ectopic renal tissue","Renal artery stenosis"],"a":3,"e":"Ectopic renal tissue (additional accessory functioning renal tissue) in pelvic/abdominal location explains dye uptake outside normal kidney positions. Renal agenesis would show only one functioning kidney without ectopic uptake.<br><br>Take Notes: Horseshoe = fused lower poles, fixed | Pelvic kidney = single ectopic location | Multiple sites of dye uptake = ectopic renal tissue."},
/*90*/ {"q":"A 3-year-old boy presents with petechiae and nosebleeds. Which initial laboratory test is best to evaluate his bleeding disorder?","o":["Bleeding time","Partial thromboplastin time (PTT)","Complete blood count (CBC)","Prothrombin time (PT)","D-dimer"],"a":2,"e":"In a child with petechiae and bleeding, CBC with platelet count is the essential first investigation to detect thrombocytopenia (most likely cause - ITP) or pancytopenia (leukemia, aplastic anemia).<br><br>Take Notes: PT/PTT = coagulation factors | Bleeding time = platelet function | Petechiae + bleeding = CBC first."},
/*91*/ {"q":"Femoral head blood supply in children:","o":["Medial and Lateral Circumflex Artery","Obturator artery","Nutrient artery","Tibial artery","Lateral circumflex only"],"a":1,"e":"In children, femoral head is supplied largely by the artery of ligamentum teres (branch of obturator artery) along with medial circumflex; this contribution diminishes in adults. Loss causes Legg-Calvé-Perthes.<br><br>Take Notes: Adult = medial circumflex predominant | Lateral circumflex = trochanter | Child femoral head = obturator artery (via ligamentum teres)."},
/*92*/ {"q":"Head of femur dural hemorrhage is caused by rupture of which of following:","o":["Berry aneurysm","Middle cerebral vein","Superior cerebral artery","Middle meningeal artery","Anterior cerebral artery"],"a":3,"e":"Epidural hematoma is caused by rupture of middle meningeal artery (branch of maxillary), typically with pterion fracture; classic presentation: lucid interval after head trauma, then deterioration.<br><br>Take Notes: Bridging veins = subdural | Berry aneurysm = SAH | Epidural = middle meningeal artery."},
/*93*/ {"q":"After trauma to head, lucid interval and again loss of consciousness:","o":["Epidural hematoma","SAH","Subdural hemorrhage","Intracerebral hemorrhage","Cerebral contusion"],"a":0,"e":"Epidural (extradural) hematoma: classic presentation with brief loss of consciousness, lucid interval (minutes-hours), then rapid deterioration as expanding arterial blood collection compresses brain. Middle meningeal artery rupture.<br><br>Take Notes: Subdural = slower venous bleed | SAH = thunderclap headache | Lucid interval = epidural hematoma."},
/*94*/ {"q":"A patient presents with history of edema. His vitals reveal increased blood pressure. Investigations reveal: hypokalemia, decreased renin levels, but Sodium and Aldosterone levels are within normal limits. A diagnosis of Liddle syndrome is made. Where is the defect located?","o":["Mutation in Epithelial sodium channel (ENaC) in the collecting duct","Sodium-potassium ATPase pump","Aldosterone receptor","Renin-angiotensin system","Na-H cotransport"],"a":0,"e":"Liddle syndrome: autosomal dominant gain-of-function mutation in ENaC (epithelial sodium channel) in collecting duct; persistent Na+ reabsorption causes hypertension with hypokalemia and low renin/aldosterone (suppressed RAAS).<br><br>Take Notes: Aldosterone normal = not Conn | Low renin + normal aldo = Liddle | ENaC gain-of-function = Liddle."},
/*95*/ {"q":"Tetanus toxin is:","o":["Endotoxin","Neurotoxin","Erythrogenic toxin","Toxoid","Exotoxin"],"a":1,"e":"Tetanospasmin is a neurotoxin (exotoxin) of Clostridium tetani; blocks inhibitory neurotransmitter (GABA/glycine) release at spinal cord, causing tetanic spastic paralysis with classic risus sardonicus and opisthotonus.<br><br>Take Notes: Endotoxin = gram-negative LPS | Erythrogenic = strep | Tetanus = neurotoxin (exotoxin)."},
/*96*/ {"q":"30-year-old male transplant patient develops Candida infection and is treated with ketoconazole. Why is this therapy problematic?","o":["Candida","Ketoconazole inactivates cyclosporine","Ketoconazole causes cardiotoxicity","Ketoconazole inhibits CYP450 enzymes increasing cyclosporine levels","Ketoconazole causes gynecomastia and decreased libido"],"a":3,"e":"Ketoconazole inhibits CYP3A4, dramatically increasing serum cyclosporine levels and causing toxicity (nephrotoxicity, hypertension). Drug interaction is clinically significant in transplant patients.<br><br>Take Notes: Ketoconazole = potent CYP3A4 inhibitor | Cyclosporine = CYP3A4 substrate | Risk = increased cyclosporine toxicity."},
/*97*/ {"q":"Pregnant female had decreased level of T3 T4 and has increase TSH. Lymphocytes are also found in it is related to:","o":["Thyroid cancer","Grave disease","Thyroid storm","Hashimoto","Idiopathic"],"a":3,"e":"Hashimoto thyroiditis: autoimmune lymphocytic infiltration of thyroid causing hypothyroidism (low T3/T4, high TSH). Lymphocytic infiltrate with germinal centres is histologic hallmark. Anti-TPO antibodies positive.<br><br>Take Notes: Grave = hyperthyroidism + TSI | Thyroid storm = severe hyperthyroid | Hypothyroid + lymphocytes = Hashimoto."},
/*98*/ {"q":"Hashimoto is common cause of Hypothyroidism and has Hurtle cells and lymphoid aggregates with germinal centers. During submandibular gland excision, injury to which of the following structures can cause paralysis of the lower lip?","o":["Marginal mandibular branch of facial nerve","Lingual nerve","Hypoglossal nerve","Glossopharyngeal nerve","Vagus nerve"],"a":0,"e":"Marginal mandibular branch of facial nerve passes near the lower border of mandible above submandibular gland; injury during surgery causes paralysis of lower lip depressor muscles, asymmetric smile.<br><br>Take Notes: Lingual = sensory tongue | Hypoglossal = motor tongue | Submandibular surgery = marginal mandibular nerve risk."},
/*99*/ {"q":"A female with hand swollen and red, and is now 20 years of age, absent secondary sexual characteristics with amenorrhea and most likely karyotype of this diagnosis is:","o":["47XXY","46XX","45XO","45XX","46XY"],"a":2,"e":"Turner syndrome (45,XO): primary amenorrhea, short stature, webbed neck, lymphedema (hand swelling), absent secondary sexual characteristics, streak ovaries, cardiac defects (coarctation), and renal anomalies.<br><br>Take Notes: 47XXY = Klinefelter (tall male, infertile) | 46XY = normal male | Female + amenorrhea + lymphedema = 45,XO."},
/*100*/ {"q":"A man presents with an inguinal swelling that worsened after lifting weights. The swelling is now warm, red, tender, and associated with severe pain and vomiting. Why is emergency surgery recommended?","o":["Incarcerated hernia with strangulation","Incarcerated hernia without strangulation","Hydrocele","Intestinal Obstruction","Reducible inguinal hernia"],"a":0,"e":"Strangulated incarcerated hernia: tense, tender, irreducible swelling with red overlying skin, vomiting, and severe pain indicate vascular compromise to bowel. Emergency surgery prevents bowel necrosis and perforation.<br><br>Take Notes: Reducible = no urgency | Incarcerated without strangulation = elective | Tender + red + vomiting = strangulation."},
/*101*/ {"q":"A patient presents with a right groin swelling located lateral and inferior to the pubic tubercle. Most likely diagnosis?","o":["Hydrocele","Indirect hernia","Femoral hernia","Varicocele","Direct hernia"],"a":2,"e":"Femoral hernia: swelling lateral and inferior to pubic tubercle (vs inguinal hernia which is medial and superior). More common in females; high risk of strangulation due to narrow femoral canal.<br><br>Take Notes: Inguinal = medial + superior to pubic tubercle | Hydrocele = scrotal | Lateral + inferior to PT = femoral hernia."},
/*102*/ {"q":"A female patient with a history of 3 C-sections presents with epigastric swelling and a non-palpable defect, cough impulse positive. Most likely diagnosis is:","o":["Femoral hernia","Epigastric hernia","Divarication of recti","Paraumblical hernia","Umbilical hernia"],"a":2,"e":"Divarication of recti: separation of rectus abdominis muscles without a palpable fascial defect, common after multiple pregnancies/C-sections. Cough impulse positive but no incarceration risk.<br><br>Take Notes: Epigastric hernia = palpable defect | Paraumbilical = umbilical area | No defect + cough impulse = divarication of recti."},
/*103*/ {"q":"An alcoholic patient presents to doctor with acute abdominal pain. Doctor diagnosed it as a case of acute pancreatitis. Which of the following laboratory test use best for confirmation?","o":["Serum amylase + CBC","Serum lipase + CBC","Serum amylase + Serum lipase","CBC","LFT"],"a":2,"e":"Acute pancreatitis diagnosis requires 2 of 3: clinical pain, raised enzymes (amylase + lipase >3x normal), imaging findings. Lipase is more specific and stays elevated longer than amylase.<br><br>Take Notes: Lipase = more specific | Amylase = early but non-specific | Acute pancreatitis = amylase + lipase."},
/*104*/ {"q":"A female patient presents in Gynae OPD with third degree UV prolapse, which occurs due to damage of uterosacral ligament. Which of the following structures attaches the uterosacral ligament to the cervix?","o":["Anterior pelvic wall","Rectum","Urinary bladder","Round ligament","Posterior pelvic wall (sacrum)"],"a":4,"e":"Uterosacral ligaments are the major posterior support of cervix and upper vagina; extend from posterolateral cervix to sacrum (S2-S4). Damage causes uterovaginal prolapse.<br><br>Take Notes: Round ligament = cervix to labia | Pubocervical = cervix to pubis | Uterosacral = cervix to sacrum (posterior pelvic wall)."},
/*105*/ {"q":"Tetracycline activity against Helicobacter pylori results from inhibition of which target?","o":["DNA gyrase","Dihydrofolate reductase","30S ribosomal subunit","Cell-wall transpeptidase","Bacterial RNA polymerase"],"a":2,"e":"Tetracyclines bind the 30S ribosomal subunit reversibly, preventing aminoacyl-tRNA attachment and protein synthesis. Used in H. pylori triple/quadruple therapy and other bacterial infections.<br><br>Take Notes: Cell-wall = β-lactams | DNA gyrase = fluoroquinolones | Tetracyclines = 30S ribosomal subunit."},
/*106*/ {"q":"Why does carbamazepine reduce nifedipine's effect?","o":["It induces cytochrome P450","Decreases absorption","Blocks receptors","Reduces renal excretion","Inhibits hepatic metabolism"],"a":0,"e":"Carbamazepine is a potent CYP3A4 (and 2C9) inducer; it accelerates hepatic metabolism of nifedipine (CYP3A4 substrate), reducing its plasma concentration and efficacy. Classic drug interaction.<br><br>Take Notes: P450 inducers = phenytoin, rifampicin, carbamazepine | P450 inhibitors = enhance levels | Carbamazepine + nifedipine = induced metabolism."},
/*107*/ {"q":"Which of the following tests is most appropriate to assess whether ovulation has occurred in a woman with 28-day menstrual cycle?","o":["Serum progesterone on day 14 (D14)","Serum progesterone on day 21 (D21)","Serum luteinizing hormone (LH) on day 10","Serum follicle stimulating hormone (FSH) on day 3","Serum estrogen on day 7"],"a":1,"e":"Mid-luteal phase progesterone (day 21 in 28-day cycle) confirms ovulation — peak progesterone secretion by corpus luteum occurs ~7 days post-ovulation. Levels >10 ng/mL confirm ovulation.<br><br>Take Notes: LH surge = pre-ovulation marker | FSH day 3 = ovarian reserve | Ovulation confirmation = day 21 progesterone."},
/*108*/ {"q":"Which describes the mechanism of tetanus toxin?","o":["Blocks acetylcholine release causing flaccid paralysis","Blocks GABA/glycine causing spastic paralysis","Inhibits dopamine receptors causing rigidity","Causes demyelination leading to weakness","Blocks sodium channels causing sensory loss"],"a":1,"e":"Tetanus toxin (tetanospasmin) cleaves synaptobrevin in inhibitory interneurons, blocking GABA and glycine release at spinal cord; loss of inhibition causes continuous motor activation and spastic (tetanic) paralysis.<br><br>Take Notes: Botulinum = blocks ACh release (flaccid) | Tetanus = blocks GABA/glycine (spastic) | Spastic paralysis = tetanus."},
/*109*/ {"q":"In hypoxic cellular injury, cell swelling primarily occurs due to:","o":["Increased intracellular water","Increased intracellular protein","Increased intracellular glycogen","Increased extracellular sodium","Increased mitochondrial ATP production"],"a":0,"e":"Hypoxia depletes ATP, failing Na+/K+-ATPase pump; sodium accumulates intracellularly, drawing water osmotically and causing hydropic cell swelling (cloudy swelling) — first morphologic change in cell injury.<br><br>Take Notes: ATP loss = pump failure | Na+ → in, water follows | Cell swelling = increased intracellular water."},
/*110*/ {"q":"Peripheral neuropathy secondary to isoniazid is reversed/prevented by:","o":["Cobalamine","Folic acid","B6 (Pyridoxine)","B1","B9"],"a":2,"e":"Isoniazid (INH) inhibits pyridoxine phosphokinase, causing functional vitamin B6 deficiency and peripheral neuropathy. Co-administration of pyridoxine (B6) prevents and reverses this complication.<br><br>Take Notes: B12 = SCD/megaloblastic | Folate = NTD | INH neuropathy prevention = B6 (pyridoxine)."},
/*111*/ {"q":"What is likely cause of mesothelioma?","o":["Cane fibres","Asbestosis","Silicosis","Ammonia","Sugar fibers"],"a":1,"e":"Asbestos exposure is the major cause of malignant pleural mesothelioma; latency period is 20-40 years. Histology shows ferruginous bodies. Smoking does not increase mesothelioma risk (unlike lung cancer).<br><br>Take Notes: Silicosis = silica nodules | Asbestos exposure = mesothelioma + lung CA risk."},
/*112*/ {"q":"TB has which type of hypersensitivity?","o":["Type 1","Type 3","Type 4","Type 2","Type 5"],"a":2,"e":"TB causes type IV (delayed) hypersensitivity: T cell-mediated response forming caseating granulomas around mycobacteria. Mantoux/PPD test demonstrates this response 48-72 hours after antigen challenge.<br><br>Take Notes: Type I = IgE allergic | Type II = antibody | Type III = immune complex | TB = type IV (cell-mediated)."},
/*113*/ {"q":"Anaphylaxis after ingestion of a drug is an example of which type of hypersensitivity?","o":["Antigen antibody complex in different tissue","Antibody in tissue","Cells in tissue","IgE mediated damage","Immune complex deposition"],"a":3,"e":"Anaphylaxis is type I hypersensitivity: IgE bound to mast cells crosslinks on antigen exposure, releasing histamine, leukotrienes, and tryptase. Causes vasodilation, bronchoconstriction, and shock within minutes.<br><br>Take Notes: Type II = antibody-mediated cell damage | Type III = immune complex | Anaphylaxis = type I (IgE-mediated)."},
/*114*/ {"q":"A child with fever, sore throat, joint pain, and positive ASO titre has tissue damage caused by:","o":["Immune complex deposition","Antibodies cross-reacting with host tissues","T-cell mediated delayed hypersensitivity","Direct bacterial toxin damage","Immune complex clearance by macrophages"],"a":1,"e":"Acute rheumatic fever: type II hypersensitivity with antibodies against streptococcal M protein cross-reacting with host cardiac, joint, and CNS tissues (molecular mimicry). Causes carditis, polyarthritis, chorea.<br><br>Take Notes: Type III = immune complex (PSGN) | Type IV = T cell | Rheumatic fever = molecular mimicry (Ab cross-reactivity)."},
/*115*/ {"q":"What is the primary mechanism by which natural killer (NK) cells kill target cells?","o":["Antibody-dependent cell-mediated cytotoxicity (ADCC)","Perforin and granzyme-induced apoptosis","Release of histamine causing inflammation","Production of reactive oxygen species (ROS)","Activation of complement cascade"],"a":1,"e":"NK cells kill via perforin (creates pores in target membrane) and granzymes (enter through pores and activate caspases) — inducing apoptosis of virally infected and tumor cells. Don't require prior sensitization.<br><br>Take Notes: ADCC = also possible via Fc receptors | Complement = humoral | NK primary = perforin + granzyme apoptosis."},
/*116*/ {"q":"Injury to greater wing of sphenoid and inferior orbital fissure damages which nerve?","o":["Oculomotor","Trochlear","Zygomatic","Lacrimal","Nasociliary"],"a":2,"e":"Zygomatic nerve (branch of V2 maxillary) traverses the inferior orbital fissure and gives off zygomaticofacial and zygomaticotemporal branches; runs along the greater wing of sphenoid and is vulnerable here.<br><br>Take Notes: Oculomotor = superior orbital fissure | Trochlear = same | Inferior orbital fissure = zygomatic nerve."},
/*117*/ {"q":"Inherited only from mother to child is:","o":["Imprinted DNA","Mitochondrial DNA","X-linked","Maternal disomy","Autosomal DNA"],"a":1,"e":"Mitochondrial DNA is inherited exclusively from the mother (oocyte cytoplasm); paternal mitochondria are eliminated during fertilization. Mitochondrial disorders (LHON, MELAS) show maternal inheritance pattern.<br><br>Take Notes: X-linked = mother → sons mainly | Imprinted = parent-specific expression | Pure maternal = mitochondrial DNA."},
/*118*/ {"q":"What is the approximate volume of distribution (VD) for most drugs?","o":["3 liters","10 liters","15 liters","40 liters","70 liters"],"a":3,"e":"Total body water in 70 kg adult is ~42L (60% body weight); most drugs distribute into total body water with VD ~40L. Plasma volume = 3L, ECF = 14L, ICF = 28L.<br><br>Take Notes: Plasma only = 3L | ECF = 14L | Total body water = 42L | Average drug VD = ~40L."},
/*119*/ {"q":"Lymphatic drainage of anterior 2/3rd of tongue is to which of the following lymph nodes?","o":["Submandibular lymph nodes","Deep cervical lymph nodes","Retropharyngeal lymph nodes","Occipital lymph nodes","Paraaortic lymph nodes"],"a":0,"e":"Anterior 2/3 of tongue drains primarily to submandibular lymph nodes (then to deep cervical); tip drains to submental nodes; posterior 1/3 drains directly to jugulo-omohyoid nodes.<br><br>Take Notes: Tip = submental nodes | Posterior 1/3 = jugulo-omohyoid | Anterior 2/3 = submandibular nodes."},
/*120*/ {"q":"Common site for ectopic thyroid tissue is:","o":["Base of tongue","Sublingual space","Lateral neck","Mediastinum","Floor of mouth"],"a":0,"e":"Lingual thyroid (base of tongue) is the most common site of ectopic thyroid tissue, resulting from failed descent during embryogenesis. May be the only thyroid tissue present and cause dysphagia.<br><br>Take Notes: Sublingual = less common | Mediastinal = retrosternal goiter | Ectopic thyroid commonest site = base of tongue."},
/*121*/ {"q":"A woman with the history of trauma to head and neck region having lesion on tongue with protrusion of tongue deviated to the left side. The nerve most likely to involve is:","o":["Left hypoglossal","Right hypoglossal","Glossopharyngeal nerve","Vagus nerve","Facial nerve"],"a":0,"e":"Tongue protrusion deviates toward the side of hypoglossal (XII) nerve lesion due to unopposed contralateral genioglossus action. Left-sided deviation = left hypoglossal nerve injury (ipsilateral LMN palsy).<br><br>Take Notes: UMN lesion = deviates away from lesion | LMN lesion = deviates toward | Left deviation = left hypoglossal."},
/*122*/ {"q":"Which of the following antibiotics is most commonly associated with causing jaundice?","o":["Erythromycin","Isoniazid","Rifampicin","Chloramphenicol","Sulfonamides"],"a":2,"e":"Rifampicin commonly causes drug-induced hepatitis with jaundice; also colors body fluids orange-red. Hepatotoxicity is dose-dependent; LFTs need monitoring during anti-tubercular treatment.<br><br>Take Notes: Erythromycin = cholestatic jaundice (less common) | INH = hepatocellular | Most common jaundice = rifampicin."},
/*123*/ {"q":"Which muscle arises from the third pharyngeal arch?","o":["Stylopharyngeus","Stylohyoid","Mylohyoid","Stapedius","Cricothyroid"],"a":0,"e":"Stylopharyngeus is the only muscle derived from third pharyngeal arch; supplied by glossopharyngeal nerve (IX). All other styloid/stylo-muscles derive from arch II (facial nerve).<br><br>Take Notes: Arch I = mastication muscles (V3) | Arch II = stylohyoid, stapedius (VII) | Arch III = stylopharyngeus (IX)."},
/*124*/ {"q":"HbA1C reflects diabetic control over approximately which time period?","o":["48 hours","Up to 1 week","4-8 weeks","8-10 weeks","10-12 weeks"],"a":4,"e":"HbA1c reflects average blood glucose over the lifespan of red blood cells (~120 days); clinically useful for 2-3 month (10-12 weeks) glycemic control assessment. Updated every 3 months.<br><br>Take Notes: Fructosamine = 2-3 weeks | Glucose = instant | HbA1c = 10-12 weeks (3 months)."},
/*125*/ {"q":"Which antidiabetic drug is associated with an increased risk of pancreatitis and urinary tract infections?","o":["Metformin","Canagliflozin","Glipizide","Sitagliptin","Pioglitazone"],"a":3,"e":"DPP-4 inhibitors (sitagliptin, saxagliptin) are associated with acute pancreatitis (FDA warning) and increased UTI risk through GLP-1 effects. SGLT2 inhibitors also cause UTI but pancreatitis is DPP-4 specific.<br><br>Take Notes: Metformin = lactic acidosis | Pioglitazone = bladder cancer | Pancreatitis + UTI = sitagliptin (DPP-4)."},
/*126*/ {"q":"A patient presents with palpitations, sweating, and pale hands. Laboratory tests show low TSH and elevated T3 and T4. Most likely diagnosis is:","o":["Graves' disease","Hashimoto's thyroiditis","Subacute thyroiditis","Euthyroid sick syndrome","Thyroid cancer"],"a":0,"e":"Graves disease: hyperthyroidism (low TSH, high T3/T4) due to TSH receptor stimulating autoantibodies (TSI). Classic features: palpitations, sweating, weight loss, tremor, exophthalmos, pretibial myxedema.<br><br>Take Notes: Subacute thyroiditis = transient, tender thyroid | Hashimoto = hypothyroid | Hyperthyroidism young woman = Graves."},
/*127*/ {"q":"Acid fast stain is positive in which of the following microbes?","o":["Bacteria","Virus","Fungi","Rickettsia","Spirochetes"],"a":0,"e":"Acid-fast bacteria (Mycobacterium, Nocardia) retain carbol fuchsin dye despite acid-alcohol decolorization due to mycolic acid in their cell walls; Ziehl-Neelsen stain detects them as bright pink rods.<br><br>Take Notes: Viruses = electron microscopy | Fungi = KOH, periodic acid | Rickettsia = Giemsa | Acid-fast = Mycobacterium (bacteria)."},
/*128*/ {"q":"In cases of renal failure on long-term haemodialysis, there is development of following type of amyloid:","o":["Amyloid light chain (AL)","Amyloid associated protein (AA)","Amyloid β2 microglobulin (Aβ2m)","β amyloid protein (Aβ)","Transthyretin amyloid"],"a":2,"e":"Long-term hemodialysis patients develop β2-microglobulin amyloidosis; this small protein is normally renally cleared but accumulates in CKD/dialysis, depositing in joints (carpal tunnel) and bones.<br><br>Take Notes: AL = light chain (myeloma) | AA = chronic inflammation | Aβ = Alzheimer | Dialysis-related = β2-microglobulin."},
/*129*/ {"q":"Lymphatic drainage of upper outer quadrant of breast:","o":["Deep cervical lymph nodes","Axillary lymph nodes","Superficial cervical lymph nodes","Internal mammary lymph nodes","Posterior intercostal lymph nodes"],"a":1,"e":"Upper outer quadrant of breast (most common cancer site) drains primarily to axillary lymph nodes (specifically anterior/pectoral group, then central and apical). Sentinel node assessment is routine.<br><br>Take Notes: Medial breast = internal mammary | Lower quadrants = some abdominal nodes | Upper outer = axillary nodes."},
/*130*/ {"q":"Common site of aortic aneurysm involvement is in which layer of the aortic wall?","o":["Intima","Tunica media","Adventitia","Serosa","Sub-endothelium"],"a":1,"e":"Aortic aneurysm involves the tunica media: loss of elastic and smooth muscle fibers causes weakening and dilation. Atherosclerosis (AAA) and cystic medial necrosis (thoracic, Marfan) are common causes.<br><br>Take Notes: Intima = atherosclerosis starts here | Adventitia = vasa vasorum | Aneurysm = tunica media weakness."},
/*131*/ {"q":"Mesangial cells have contractile properties that help maintain which of the following functions?","o":["Hemoglobin synthesis","Aldosterone secretion","Renal blood flow","Blood pressure","Glomerular filtration"],"a":2,"e":"Mesangial cells in glomeruli have contractile properties (myofibroblast-like); they regulate glomerular blood flow and filtration surface area in response to angiotensin II, ADH, and other stimuli.<br><br>Take Notes: Juxtaglomerular cells = renin | Macula densa = NaCl sensing | Mesangial contraction = regulates renal blood flow + GFR."},
/*132*/ {"q":"Auer rods are seen in which of the following condition?","o":["Polycythemia rubra vera","CML","ALL","CLL","AML"],"a":4,"e":"Auer rods are crystalline aggregates of myeloperoxidase within azurophilic granules, characteristic of acute myeloid leukemia (AML), especially the M3 subtype (acute promyelocytic leukemia, t(15;17)).<br><br>Take Notes: ALL = TdT positive | CLL = smudge cells | CML = Philadelphia (BCR-ABL) | Auer rods = AML."},
/*133*/ {"q":"A baby's intestine does not get back. Abdominal contents are covered with amniotic layer. Most possible diagnosis is:","o":["Gastroschisis","Omphalocele","Meckel's diverticulum","Intussusception","Volvulus"],"a":1,"e":"Omphalocele: midline abdominal wall defect at umbilicus where intestines herniate covered by peritoneum, Wharton's jelly, and amniotic membrane. Associated with chromosomal anomalies (trisomy 13, 18, 21).<br><br>Take Notes: Gastroschisis = no covering, right of umbilicus | Meckel = ileal diverticulum | Covered abdominal wall defect = omphalocele."},
/*134*/ {"q":"What is the classic lesion seen in Crohn's disease?","o":["Skip lesions","Flask-shaped ulcer","Pseudopolyps","Crypt abscess","Macrophages laden lamina propria"],"a":0,"e":"Crohn disease: discontinuous (skip) lesions affecting any part of GI tract from mouth to anus, transmural inflammation, non-caseating granulomas, fistula formation, and \"cobblestone\" mucosa appearance.<br><br>Take Notes: UC = continuous, rectum + colon, mucosal | Flask ulcer = amoebiasis | Crohn = skip lesions (transmural)."},
/*135*/ {"q":"Lymphatic drainage of Upper Outer Quadrant of Breast:","o":["Deep cervical lymph nodes","Axillary lymph nodes","Superficial cervical lymph nodes","Internal mammary","Supraclavicular"],"a":1,"e":"Upper outer quadrant of breast drains primarily to anterior axillary nodes (pectoral group), then through central to apical axillary nodes. Sentinel node biopsy assesses this pathway in breast cancer staging.<br><br>Take Notes: Medial breast = internal mammary | Lower medial = epigastric | Upper outer = axillary."},
/*136*/ {"q":"The most common site of involvement is in which layer of the aortic wall?","o":["Small cell carcinoma of lung","Large cell carcinoma of lung","Carcinoid of lung","Adenocarcinoma of larynx","Squamous cell carcinoma of larynx"],"a":0,"e":"Small cell lung carcinoma (SCLC) is strongly associated with smoking and paraneoplastic syndromes including ectopic ACTH (Cushing), SIADH, and Lambert-Eaton myasthenic syndrome.<br><br>Take Notes: Squamous cell = PTHrP (hypercalcemia) | Carcinoid = serotonin | Smoking + ectopic ACTH = small cell."},
/*137*/ {"q":"Asbestos and tobacco smoking can cause:","o":["Bladder carcinoma","Bronchogenic carcinoma","Lymphoma","Malignant mesothelioma","Liver carcinoma"],"a":3,"e":"Asbestos exposure causes mesothelioma (latency 20-40 years); tobacco does NOT increase mesothelioma risk (unlike lung cancer). The combination synergistically increases lung cancer risk dramatically.<br><br>Take Notes: Lung cancer = asbestos + smoking synergy | Bladder = aniline dyes | Asbestos-specific tumor = mesothelioma."},
/*138*/ {"q":"After how long HbA1C should be repeated to estimate long-term control of blood sugar?","o":["6 months","2 months","4 months","1 month","3 months"],"a":4,"e":"HbA1c is measured every 3 months for diabetic monitoring; reflects average glucose over erythrocyte lifespan (~120 days). 6-month intervals acceptable in stable, well-controlled patients.<br><br>Take Notes: RBC lifespan ~120 days | Reflects 8-12 week average | Standard HbA1c repeat = 3 months."},
/*139*/ {"q":"Medullary CA tumor marker is:","o":["CA 125","CA 19-9","Calcitonin","CA 15-5","ALP"],"a":2,"e":"Medullary thyroid carcinoma arises from parafollicular C cells secreting calcitonin; serum calcitonin is the specific tumor marker. Also produces CEA. Associated with MEN2A and MEN2B syndromes.<br><br>Take Notes: CA 125 = ovarian | CA 19-9 = pancreatic | CA 15-3 = breast | Medullary thyroid = calcitonin."},
/*140*/ {"q":"Cell stain basophilia is due to:","o":["Ribosome","Lysosomes","SER","Peroxisomes","Mitochondria"],"a":0,"e":"Basophilia (blue staining with basic dyes like hematoxylin) is due to high concentration of ribosomes and ribosomal RNA in cytoplasm; characteristic of actively protein-synthesizing cells (plasma cells, hepatocytes).<br><br>Take Notes: Eosinophilia = acidophilic proteins (cytoplasm) | Lysosomes = enzymes | Basophilia cell stain = ribosomes (rRNA)."},
/*141*/ {"q":"A 25-year-old female presents with retro-orbital headache, fever and joint pain after travel to a tropical region. Lab shows thrombocytopenia and positive NS1 antigen. Most likely diagnosis?","o":["Malaria","Dengue fever","Typhoid","Chikungunya","Yellow fever"],"a":1,"e":"Dengue fever: tropical travel + retro-orbital headache + thrombocytopenia + positive NS1 antigen is diagnostic. Aedes mosquito-borne; risk of dengue hemorrhagic fever/shock syndrome with secondary infection.<br><br>Take Notes: Malaria = thick/thin smear | Chikungunya = joint pain dominant | NS1 + thrombocytopenia = dengue."},
/*142*/ {"q":"A 6-year-old boy presents with recurrent skin and lung infections from catalase-positive organisms. Nitroblue tetrazolium (NBT) test is negative. Most likely diagnosis?","o":["Chronic granulomatous disease","Severe combined immunodeficiency","Wiskott-Aldrich syndrome","Bruton's agammaglobulinemia","DiGeorge syndrome"],"a":0,"e":"Chronic granulomatous disease (CGD): X-linked NADPH oxidase defect causing impaired neutrophil respiratory burst. Negative NBT test confirms it; recurrent catalase-positive infections (Staph aureus, Aspergillus, Burkholderia).<br><br>Take Notes: SCID = T+B cell defects | Bruton's = no B cells | Catalase+ infections + NBT negative = CGD."},
/*143*/ {"q":"Which of the following is most common tumor of salivary glands?","o":["Pleomorphic Adenoma","Warthin Tumor","Mucoepidermoid carcinoma","SCC","Adenoid cystic carcinoma"],"a":0,"e":"Pleomorphic adenoma (mixed tumor) is the most common salivary gland tumor (60-70%), most often in parotid. Benign but with malignant transformation potential; complete excision required to prevent recurrence.<br><br>Take Notes: Warthin = bilateral, smokers | Mucoepidermoid = commonest malignant | Most common overall = pleomorphic adenoma."},
/*144*/ {"q":"Which of the following anti-HIV drugs is contraindicated in pregnancy?","o":["Zidovudine","Efavirenz","Lamivudine","Nevirapine","Tenofovir"],"a":1,"e":"Efavirenz is teratogenic in first trimester (neural tube defects in animal studies); category D in pregnancy. Zidovudine, lamivudine, and tenofovir are preferred and used to prevent mother-to-child HIV transmission.<br><br>Take Notes: Zidovudine = ART of choice (PMTCT) | Nevirapine = preferred PMTCT | Teratogenic in pregnancy = efavirenz."},
/*145*/ {"q":"First step between doctor and patient relationship should be:","o":["Informed working","Mutual trust","Mutual respect","Mutual benefit","Confidentiality"],"a":1,"e":"Mutual trust is the foundation of doctor-patient relationship; established through honest communication, competence demonstration, and confidentiality. Trust facilitates honest disclosure, adherence, and shared decision-making.<br><br>Take Notes: Respect/benefit/confidentiality = important pillars | Foundation = mutual trust."},
/*146*/ {"q":"Before starting oral anticoagulant warfarin therapy, what test should be performed in order to analyze warfarin activity?","o":["PT/APTT","INR","APTT","PT/INR","D-dimer"],"a":3,"e":"Warfarin therapy is monitored by PT/INR; baseline PT/INR is essential before starting to assess baseline coagulation status and to titrate dose. Target INR depends on indication (2.0-3.0 for most).<br><br>Take Notes: APTT = heparin monitoring | D-dimer = thrombosis | Warfarin baseline + monitoring = PT/INR."},
/*147*/ {"q":"Patient c/o tingling sensation due to post thyroidectomy thyroid cancer which of the following is likely cause:","o":["Cretinism","Myxedema","Low Calcium","High PTH","Hyperthyroidism"],"a":2,"e":"Post-thyroidectomy hypocalcemia occurs when parathyroid glands are inadvertently devascularized or removed; low calcium increases neuromuscular excitability causing tingling, paresthesia, and tetany within hours to days.<br><br>Take Notes: Hoarseness = recurrent laryngeal nerve | Hypothyroidism = myxedema | Post-thyroidectomy tingling = hypocalcemia."},
/*148*/ {"q":"In Gaucher disease there is deficiency of:","o":["Hexosaminidase A","Glucocerebrosidase","Fructokinase","Hexokinase","Glucokinase"],"a":1,"e":"Gaucher disease: deficient glucocerebrosidase causes glucocerebroside accumulation in macrophages (Gaucher cells with \"crumpled tissue paper\" cytoplasm); presents with hepatosplenomegaly, pancytopenia, bone pain. Most common LSD.<br><br>Take Notes: Hexosaminidase A deficiency = Tay-Sachs | Fructokinase = essential fructosuria | Gaucher = glucocerebrosidase."},
/*149*/ {"q":"Loss of functional mutation in which gene cause cancer?","o":["APC","BCL3","TP53","BCL2","KRAS"],"a":2,"e":"TP53 is the most common tumor suppressor gene mutated in human cancers; loss-of-function mutations remove the \"guardian of the genome\" — p53 normally arrests cell cycle and triggers apoptosis upon DNA damage.<br><br>Take Notes: APC = FAP, colon | BCL2 = anti-apoptotic (gain) | KRAS = oncogene (gain) | Loss-of-function in tumor suppressor = TP53."},
/*150*/ {"q":"A pregnant woman is taking phenytoin. Which of the following is the least likely complication in the fetus?","o":["Bone deformity","Gingival hyperplasia","Cleft palate","Nail hypoplasia","Cardiac defects"],"a":1,"e":"Fetal hydantoin syndrome: cleft lip/palate, nail/distal phalanx hypoplasia, microcephaly, cardiac defects, intellectual disability. Gingival hyperplasia is a side effect in patient taking phenytoin, NOT a fetal complication.<br><br>Take Notes: Cleft + nail hypoplasia + cardiac = fetal hydantoin | Gingival hyperplasia = mother's side effect, not fetus."},
];
